 "content": "from collections import Counter


def transform(grid):
    """Fill each rectangular frame with a checkerboard of a clue color.

    The nonzero marks outside the frames occur as many times as the number
    of checkerboard cells in the corresponding frame interior.
    """
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, _ in comp)
            r1 = max(y for y, _ in comp)
            c0 = min(x for _, x in comp)
            c1 = max(x for _, x in comp)
            perimeter = {(y, x) for y in range(r0, r1 + 1)
                         for x in range(c0, c1 + 1)
                         if y in (r0, r1) or x in (c0, c1)}
            if r1 - r0 >= 2 and c1 - c0 >= 2 and set(comp) == perimeter:
                frames.append((r0, r1, c0, c1, color))

    frame_cells = {(r, c) for r0, r1, c0, c1, _ in frames
                   for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)}
    clue_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                          if grid[r][c] != 0 and (r, c) not in frame_cells)
    out = [[0] * w for _ in range(h)]
    for r0, r1, c0, c1, frame_color in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = frame_color
        checker_cells = [(r, c) for r in range(r0 + 1, r1)
                         for c in range(c0 + 1, c1)
                         if (r - r0 - 1 + c - c0 - 1) % 2 == 0]
        matches = [color for color, count in clue_counts.items()
                   if color != frame_color and count == len(checker_cells)]
        if len(matches) != 1:
            raise ValueError((frames, clue_counts, len(checker_cells), matches))
        for r, c in checker_cells:
            out[r][c] = matches[0]
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
